head.script:
scwin.gVar = {
    "cDisabled" : "",
    "cReadOnly" : "",
    "nCount_1" : 0,
}



// 테스트 설명, 유효성 값 설정
//  - @spec 의 "Event Object 의 설명은 표준 속성만을 다루고 있으며 웹브라우저에 따라 일부 차이가 있을 수 있습니다." 는
//    브라우저 구현 차이에 대한 안내 문구로 확인 수단을 만들 수 없어 유효성에서 제외한다. (secret_E_onblur_1, secret_E_onmousedown_1 선례)
//  - e 객체의 개별 속성(e.clientX, e.movementX, e.offsetX 등)은 표준 DOM 이벤트 속성이라 개별 유효성으로 만들지 않는다.
//  - onmousemove 가이드에는 이벤트 발생 순서 @spec 이 없으므로 @related 의 onmouseover / onmouseout 은 바인딩하지 않는다.
scwin.tData = {
    "description" : "[secret > E > onmousemove]<br/>Secret 컴포넌트 영역에서 마우스 포인터가 이동할 때 발생합니다.",
    "validation" : [
        "Secret 컴포넌트 영역에서 마우스 포인터가 이동할 때 onmousemove 이벤트가 발생합니다.",
        "이벤트 핸들러에 MouseEvent 객체 e 가 전달됩니다.",
        "마우스 이동에 따라 이벤트가 연속적으로 발생합니다.",
        "disabled=true 인 경우 onmousemove 이벤트가 발생하지 않지만 readOnly=true 인 경우엔 onmousemove 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 코드값 1 = 미설정)
    con_disabled.setValue("1");
    con_readOnly.setValue("1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[절차] 조건 선택 후 Target 재생성 -> 결과창 clear -> target1 입력창 위에서 마우스 포인터를 천천히 움직입니다\n[확인] 연속 발생하므로 앞 3회까지만 출력하고 3회째 줄 뒤에 ... 를 덧붙입니다\n[확인] 출력 횟수는 Target 재생성 시에만 초기화되므로 결과창 clear 만으로는 다시 출력되지 않습니다"', '', 'label1');

    // 출력 카운터 초기화
    scwin.gVar["nCount_1"] = 0;

    // 조건 설정
    scwin.gVar["cDisabled"] = con_disabled.getText();
    scwin.gVar["cReadOnly"] = con_readOnly.getText();

    let properties = {
        disabled : scwin.gVar["cDisabled"],
        readOnly : scwin.gVar["cReadOnly"],
    }

    let cList = $c.gcm.createCList(properties);

    let eList = $c.gcm.createEList(["onmousemove"]);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList, eList);
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// 테스트 샘플의 이벤트 처리 (마우스 포인터 이동) - validation 1, 2, 3, 4 판정 출력
//  - 마우스 이동 중 연속 발생하므로 앞 3회만 출력하고 3회째에 ... 를 덧붙인다.
scwin.target1_onmousemove = function (e) {
    if (scwin.gVar["nCount_1"] < 3) {
        wf_body_bottom.getObj("scwin").setReturnValue("▶ onmousemove (disabled " + scwin.fn_disp(scwin.gVar["cDisabled"]) + " / readOnly " + scwin.fn_disp(scwin.gVar["cReadOnly"]) + ")");
        wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);

        if (scwin.gVar["nCount_1"] == 2) {
            wf_body_bottom.getObj("scwin").setReturnValue("...");
        }
    }

    scwin.gVar["nCount_1"] += 1;
}
